class Solution:
    def hIndex(self, citations: list[int]) -> int:
        n = len(citations)
        left, right = 0, n
        while left < right:
            mid = (left + right) // 2
            if citations[mid] + mid >= n:
                right = mid
            else:
                left = mid + 1
        return n - left

